# SaleHop bug fixes: stale "Saved" favorites + favorite-star text overlap
# - Fix 1: the Saved nav badge could show a count (e.g. "2") that didn't
#   match what Your Route actually displayed, all the way down to a
#   confusingly empty Your Route screen even though the badge said there
#   were stops. Root cause: a favorited sale going stale (its date passing
#   -- sales are never auto-deleted -- or it getting deleted/un-approved
#   entirely) never got cleaned out of the saved list, so the badge kept
#   counting it forever with no way to un-star it since there was nothing
#   left to tap the star on. Now, once sales and ads have loaded for real,
#   the app quietly drops any favorited sale whose date has passed (or
#   that no longer exists at all) from the saved list -- a favorited
#   store/ad is exempt from the date check since it isn't a one-time
#   event. This cleans up any *already-stale* favorites the next time
#   each visitor's browser opens the app; it doesn't change how listings
#   themselves work (still no auto-delete of old listings -- see
#   build_status.md's "Possible follow-ups").
# - Fix 2: a sale/ad card's title text could get visually covered by the
#   round favorite star whenever the title was long enough to wrap to a
#   second line (the star sat right on top of it). Fixed with a small CSS
#   change that reserves permanent space for the star so title/address/tag
#   text can never wrap underneath it, no matter how long the title is.
# - Touches: components/AppShell.js, app/globals.css. No database
#   migration, no new npm package -- just app code.

if (-not (Test-Path "package.json")) {
    Write-Host "ERROR: package.json not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}
if (-not (Test-Path ".git")) {
    Write-Host "ERROR: .git folder not found. Run this script from inside your salehop project folder." -ForegroundColor Red
    exit 1
}

[System.IO.Directory]::SetCurrentDirectory((Get-Location).Path)

$dir_appshell = "components"
[System.IO.Directory]::CreateDirectory($dir_appshell) | Out-Null
